using System;using System.IO;using System.Drawing;using System.Windows.Forms;using Microsoft.Win32;
namespace FocusGrowth {
public sealed class DesktopIntegration:IDisposable {
 readonly NotifyIcon tray;bool exit;readonly Form form;
 public DesktopIntegration(Form window,ContinuousController controller,DeviceSessions devices,bool synthetic){form=window;var menu=new ContextMenuStrip();menu.Items.Add("Open Focus & Growth",null,(s,e)=>{form.Show();form.WindowState=FormWindowState.Normal;form.Activate();});menu.Items.Add("Pause synchronization",null,(s,e)=>controller.Pause());menu.Items.Add("Resume synchronization",null,(s,e)=>{try{controller.ResumeCurrent();}catch(Fault f){MessageBox.Show(form,f.Code);}});
 menu.Items.Add("Trusted browsers / revoke",null,(s,e)=>{using(var manager=new Form{Text="Trusted browsers — permanent until revoked",Width=750,Height=360,StartPosition=FormStartPosition.CenterParent}){var list=new ListBox{Dock=DockStyle.Fill};var button=new Button{Dock=DockStyle.Bottom,Height=45,Text="Revoke selected browser (keep all task data)"};Action refresh=()=>{list.Items.Clear();foreach(var row in devices.List())list.Items.Add(new Item{Value=J.Obj(J.Parse(J.Dump(row)))});};button.Click+=(a,b)=>{var item=list.SelectedItem as Item;if(item==null)return;devices.Revoke((string)item.Value["id"],(string)item.Value["origin"]);controller.Pause();refresh();};manager.Controls.Add(list);manager.Controls.Add(button);refresh();manager.ShowDialog(form);}});
 menu.Items.Add("Revoke production write authorization",null,(s,e)=>controller.RevokeAuthorization());
 if(!synthetic){var startup=new ToolStripMenuItem("Start at Windows sign-in (optional)");using(var key=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run")){startup.Checked=key!=null&&key.GetValue("FocusGrowthSyncV04")!=null;}startup.Click+=(s,e)=>{try{using(var key=Registry.CurrentUser.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run")){if(startup.Checked){key.DeleteValue("FocusGrowthSyncV04",false);startup.Checked=false;}else{string exe=Application.ExecutablePath;key.SetValue("FocusGrowthSyncV04","\""+exe+"\" --production-readonly");startup.Checked=true;}}}catch{MessageBox.Show(form,"Startup preference could not be saved. No security settings changed.");}};menu.Items.Add(startup);}
 menu.Items.Add("Exit (preserve enable/pause preference)",null,(s,e)=>{exit=true;form.Close();});tray=new NotifyIcon{Icon=SystemIcons.Application,Text="Focus & Growth trusted sync",Visible=true,ContextMenuStrip=menu};tray.DoubleClick+=(s,e)=>{form.Show();form.WindowState=FormWindowState.Normal;form.Activate();};form.Resize+=(s,e)=>{if(form.WindowState==FormWindowState.Minimized)form.Hide();};form.FormClosing+=(s,e)=>{if(!exit&&e.CloseReason==CloseReason.UserClosing){e.Cancel=true;form.Hide();}};
 }
 sealed class Item {public System.Collections.Generic.Dictionary<string,object> Value;public override string ToString(){return Value["origin"]+" | trusted="+Value["active"]+" | "+Value["createdUtc"]+" | "+Value["id"];}}
 public void Dispose(){tray.Visible=false;tray.Dispose();}
}
}
